import java.util.Scanner;

public class Main {
    static long n, m, mod;
    static long[][] matrix;

    static long[][] multiply(long[][] one, long[][] two) {
        int size = (int) m;
        long[][] res = new long[size][size];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                for (int k = 0; k < size; k++) {
                    res[i][j] += (one[i][k] * two[k][j]) % mod;
                    res[i][j] %= mod;
                }
            }
        }
        return res;
    }

    static long[][] power(long exp, long[][] base) {
        if (exp == 1) {
            return base;
        }

        long[][] res = power(exp / 2, base);
        res = multiply(res, res);
        if ((exp & 1) == 1) {
            res = multiply(res, base);
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        StringBuilder sb = new StringBuilder();

        mod = 1000000007;
        n = scanner.nextLong();
        m = scanner.nextLong();

        if (n < m) {
            sb.append("1");
            System.out.print(sb);
            return;
        }
        if (n == m) {
            sb.append("2");
            System.out.print(sb);
            return;
        }

        int size = (int) m;
        matrix = new long[size][size];
        matrix[0][0] = 1;
        matrix[0][size - 1] = 1;
        for (int i = 1; i < size; i++) {
            matrix[i][i - 1] = 1;
        }

        long[][] result = power(n, matrix);
        System.out.println(result[0][0]);
    }
}
